-- org_combined
SELECT owner, tupleElement(k, 1) AS day_s, tupleElement(k, 2) AS actor,
  countIf(event_type = 'PushEvent') AS push,
  countIf(event_type = 'PullRequestEvent') AS pr,
  countIf(event_type = 'IssuesEvent') AS issues,
  countIf(event_type = 'ReleaseEvent') AS release,
  count() AS n_all,
  formatDateTime(min(created_at), '%Y-%m-%d %H:%i:%S', 'UTC') AS first_ts,
  formatDateTime(max(created_at), '%Y-%m-%d %H:%i:%S', 'UTC') AS last_ts,
  formatDateTime(minIf(created_at, event_type = 'PushEvent'), '%Y-%m-%d %H:%i:%S', 'UTC') AS first_push_ts
FROM (SELECT lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS owner, created_at, event_type, lower(actor_login) AS al
      FROM github_events
      WHERE owner IN ('quicknode', 'quobyte', 'quotabook', 'rabbet', 'railbirdexchange', 'raiyee', 'ramotion', 'raptorjs', 'raptormaps', 'raumfeld', 'raycast', 'razorpay', 'reactwise', 'ready', 'readyforzero', 'realartists', 'realcrowd', 'realm', 'rebulk', 'recidiviz', 'reclaimprotocol', 'recurrency', 'redcarpetup', 'redington', 'redspread', 'refreshaustin', 'remihq', 'remix', 'remoracarbon', 'remugio', 'rendalomaq', 'renuo', 'replicate', 'replit', 'requestly', 'rescuetime', 'resend', 'reshapebiotech', 'resolvebim', 'restocks', 'rethinkdb', 'retracesoftware', 'revenuecat', 'reverielabs', 'reworkd', 'rgeo', 'ridecell', 'rigetti', 'riis', 'rippling', 'riscalab', 'riveterhq', 'rivetlogic', 'roboflow', 'robohow', 'roboticscenter', 'robotsconf', 'rocketable', 'rollstack', 'roserocket', 'rowboatlabs', 'rubble', 'rubbrband', 'rulebricks', 'runahr', 'rune', 'runharbor', 'saasquatch', 'sablono', 'safebeat', 'safelyfinance', 'saferactive', 'sailsjs', 'sakneen', 'saleswhale', 'sanvivo', 'sbxrobotics', 'scentbird', 'scicloj', 'scienceexchange', 'scispike', 'scopear', 'scrapinghub', 'screenhero', 'screenleap', 'scribd', 'scrimba', 'sealcode', 'searchly', 'secoda', 'secondmeasure', 'segmed', 'seismicgames', 'sendbird', 'sendhub', 'sentrysoftware', 'sequencebio', 'serpentine-h2020', 'sf-tensor', 'sfstoolbox', 'shadeform', 'shapescale', 'shipblu', 'shipbob', 'shoobs', 'shopify', 'shortstorybox', 'showpass', 'shredvideo', 'shuklagroup', 'sierrawireless', 'signadot', 'signoz', 'sigopt', 'silimate', 'simperium', 'simplelegal', 'simpleweb', 'simplyinsured', 'singlestore', 'skaylink', 'sketchbox3d', 'skydropx', 'sleeksys', 'smartfile', 'smashingboxes', 'snackpass', 'snapboard', 'snapcalorie', 'snapjoy', 'snh48live', 'soabridge', 'softa', 'softlibrary', 'softwareinmotion', 'softwaremarbles', 'sola-solutions', 'solutiondrive', 'solvers', 'songkick', 'soraban', 'soundboks', 'sovity', 'soyhenry', 'spaconference', 'speedledger', 'speedscale', 'spennyapp', 'spherity', 'spruceid', 'sqreen', 's