 'virt2real', 'virtualmin', 'virtualq', 'visiolab', 'vogent', 'volantio', 'voquill', 'votealign', 'vulpark', 'wallbit', 'wanderlog', 'wapim', 'wapinfotech', 'warrenmusic', 'wasp-lang', 'watchsend', 'wattcarbon', 'wearede', 'webflow', 'webgriffe', 'webiny', 'wefunder', 'wegotcoders', 'wepay', 'wetransform', 'winfunc', 'wireclub', 'wirelane', 'wisr', 'withbenchmark', 'withclad', 'withconfetti', 'withflint', 'withkash', 'wolfnet', 'womenwhocode', 'workato', 'worklytics', 'writesonic', 'wuklab', 'wyndly', 'xendit', 'xfaang', 'xgenomes', 'xirsys', 'yadaming', 'yeleman', 'yexlabs', 'yourmechanic', 'yseop', 'yummysuperapp', 'zapier', 'zeeg', 'zeloscloud', 'zencoder', 'zensors', 'zenysis', 'zeonsystems', 'zeplin', 'zerocater', 'zeroheight', 'zeropass', 'zerosettle', 'zerotech', 'zillabyte', 'zone-delta', 'zuddl') AND created_at < toDateTime('2020-01-01 00:00:00', 'UTC')
        AND actor_login != '' AND NOT match(lower(actor_login), '(\\[bot\\]$|-bot$|^dependabot|^renovate|^github-actions|^greenkeeper)'))
ARRAY JOIN [(toString(toDate(created_at, 'UTC')), ''), ('', al)] AS k
GROUP BY owner, day_s, actor
ORDER BY owner, day_s, actor
LIMIT 500001
FORMAT TSVWithNames
